def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    op_c = 0
    for _, b in history:
        if b == 'C':
            op_c += 1
    op_d = n - op_c

    w = min(10, n)
    recent_opp_c = 0
    for _, b in history[-w:]:
        if b == 'C':
            recent_opp_c += 1
    recent_op_defects = w - recent_opp_c

    def_run = 0
    i = n - 1
    while i >= 0:
        if history[i][1] == 'D':
            def_run += 1
            i -= 1
        else:
            break

    coop_run = 0
    if def_run == 0:
        i = n - 1
        while i >= 0:
            if history[i][1] == 'C':
                coop_run += 1
                i -= 1
            else:
                break

    after_D_C = 0
    after_D_D = 0
    recD_C = 0
    recD_D = 0
    ev_recent_start = max(1, n - 15)
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                after_D_C += 1
                if i >= ev_recent_start:
                    recD_C += 1
            else:
                after_D_D += 1
                if i >= ev_recent_start:
                    recD_D += 1

    hard = (op_c == 0) or (recent_op_defects >= 9) or (recent_opp_c == 0 and def_run >= 3)
    if not hard and op_d > op_c * 2 and recent_opp_c <= 2 and def_run >= 3:
        hard = True

    cooperative = (op_c > op_d) or (op_c * 3 > n and recent_opp_c * 2 > w) or (op_c == n)

    periodic = False
    if n >= 20 and not hard and cooperative:
        seq_len = min(30, n)
        start = n - seq_len
        seq = [history[i][1] for i in range(start, n)]
        D_count = sum(1 for x in seq if x == 'D')
        if 4 <= D_count <= seq_len - 4:
            mstart = max(1, n - 20)
            mirror = 0
            mtot = 0
            for i in range(mstart, n):
                mtot += 1
                if history[i][1] == history[i - 1][0]:
                    mirror += 1
            mirror_rate = mirror / mtot if mtot > 0 else 1.0
            if mirror_rate < 0.72:
                maxp = min(8, seq_len // 2)
                for p in range(2, maxp + 1):
                    tot = seq_len - p
                    if tot >= 8:
                        match = 0
                        for j in range(p, seq_len):
                            if seq[j] == seq[j - p]:
                                match += 1
                        if match / tot >= 0.75:
                            periodic = True
                            break
        if periodic and after_D_D >= after_D_C and recD_D > recD_C:
            periodic = False

    exploit = False
    if after_D_C >= 1 and after_D_C > after_D_D and cooperative:
        if after_D_C + after_D_D <= 3 or recD_C > recD_D:
            exploit = True

    if hard:
        return 'D'
    if recent_op_defects >= 8:
        return 'D'
    if periodic:
        return 'D'
    if exploit and (last_opp == 'C' or recent_op_defects <= 2):
        return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_op_defects >= 6:
                return 'D'
            if op_c > 0 and recent_opp_c > 0:
                return 'C'
            return 'D'

        if recent_op_defects >= 6 and def_run >= 2:
            return 'D'
        if after_D_D >= 1 and def_run >= 2:
            return 'D'

        if cooperative:
            if def_run <= 1:
                return 'C'
            if def_run <= 4 and recent_opp_c >= 5:
                return 'C'

        if recent_opp_c <= 3 and op_d >= op_c:
            return 'D'
        return 'D'

    # last_opp == 'C'
    if last_my == 'D':
        return 'C'

    if n < 85 and coop_run >= 30 and cooperative and after_D_D == 0 and recent_op_defects <= 2:
        if rng.random() < 0.03:
            return 'D'

    return 'C'
